import java.util.concurrent.Callable;
import java.util.concurrent.ThreadLocalRandom;

public class ResilientExecutor {
    public static <T> T executeWithRetry(Callable<T> task, int maxAttempts, long baseDelayMs) throws Exception {
        int attempt = 0;
        while (true) {
            try {
                return task.call();
            } catch (Exception e) {
                attempt++;
                if (attempt >= maxAttempts || !isTransient(e)) {
                    throw e;
                }
                long backoff = (long) (baseDelayMs * Math.pow(2, attempt));
                long jitter = ThreadLocalRandom.current().nextLong(0, 1000);
                Thread.sleep(backoff + jitter);
            }
        }
    }

    private static boolean isTransient(Exception e) {
        // Domain logic to filter retryable network/timeout exceptions from 4xx client errors
        return e instanceof java.net.SocketTimeoutException;
    }
}
